  c::Adult: Relational { ~filter [c::DB]Grown ~mainTable [c::DB]PERSON name: [c::DB]PERSON.NAME }
  c::Employment: Relational { AssociationMapping ( firm: [c::DB]@PersonFirm, employees: [c::DB]@PersonFirm ) }
)
